async fn quiz_create(State(s): State<AppState>, Form(p): Form<QuizParams>) -> AppResult {
    let errors = validate_title(&p.title);
    if !errors.is_empty() {
        return Ok(unprocessable(views::quiz_form(None, &p.title, &errors)));
    }
    let id = db::create_quiz(&s.conn(), p.title.trim())?;
    Ok(see_other(format!("/moderate/quizzes/{id}")))
}

